// Simulate a vending machine and return the messages it prints, in order.
// Slot k (0-based) sells an item for prices[k] cents (a positive multiple of 5) and
// holds stock[k] items. Credit starts at 0. An event is words separated by single
// spaces; an integer argument is an optional '-' then 1 to 9 ASCII digits.
// - "coin V": V in 5, 10, 25, 100 adds V to the credit and prints nothing. Any other
//   integer V, or a coin that would raise the credit above 500, prints "reject V"
//   and leaves the credit unchanged.
// - "select K": if K is not a slot, print "no slot K"; else if the slot is empty,
//   print "sold out K"; else if the credit is below the price, print "insert D"
//   (D is the missing amount); else print "vend K", remove one item from the slot,
//   subtract the price from the credit and, if credit remains, return it as change.
// - "refund": return the credit as change, or print "nothing" if the credit is 0.
// - Anything else (unknown word, missing, extra or malformed argument) prints
//   "error" and changes nothing.
// Returning change prints "change " then the coins joined by "+", largest first,
// using as many 100s as possible, then 25s, 10s, 5s; the credit becomes 0.
// Examples:
//   vending_machine([65], [2], ["coin 100", "select 0"]) == ["vend 0", "change 25+10"]
//   vending_machine([50, 30], [1, 0], ["coin 25", "select 0", "select 1", "refund", "refund"]) == ["insert 25", "sold out 1", "change 25", "nothing"]
fn vending_machine(prices: List[Int], stock: List[Int], events: List[Str]) -> List[Str] {
  let mut sold: Map[Int, Int] = map_new();
  let mut credit = 0;
  let mut out: List[Str] = [];
  for event in events {
    let words = split(event, " ");
    let arg = if len(words) == 2 { parse_arg(words[1]) } else { None };
    if words == ["refund"] {
      out = push(out, if credit > 0 { change_msg(credit) } else { "nothing" });
      credit = 0;
    } else {
      match (words[0], arg) {
        ("coin", Some(v)) => {
          if contains([5, 10, 25, 100], v) && credit + v <= 500 {
            credit = credit + v;
          } else {
            out = push(out, "reject " ++ show(v));
          }
        },
        ("select", Some(k)) => {
          let taken = unwrap_or(map_get(sold, k), 0);
          if k < 0 || k >= len(prices) {
            out = push(out, "no slot " ++ show(k));
          } else if stock[k] - taken == 0 {
            out = push(out, "sold out " ++ show(k));
          } else if credit < prices[k] {
            out = push(out, "insert " ++ show(prices[k] - credit));
          } else {
            out = push(out, "vend " ++ show(k));
            sold = map_set(sold, k, taken + 1);
            credit = credit - prices[k];
            if credit > 0 {
              out = push(out, change_msg(credit));
              credit = 0;
            }
          }
        },
        _ => {
          out = push(out, "error");
        },
      }
    }
  }
  out
}

fn parse_arg(word: Str) -> Option[Int] {
  let digits = if starts_with(word, "-") { substr(word, 1, str_len(word)) } else { word };
  if str_len(digits) == 0 || str_len(digits) > 9 || !all(chars(digits), |c| is_digit(c)) {
    return None;
  }
  parse_int(word)
}

fn change_msg(amount: Int) -> Str {
  let mut left = amount;
  let mut coins: List[Str] = [];
  for coin in [100, 25, 10, 5] {
    while left >= coin {
      coins = push(coins, show(coin));
      left = left - coin;
    }
  }
  "change " ++ join(coins, "+")
}
